(function(root){
'use strict';
// Keep every published rule layer intact so prior actions replay exactly.
const browser=typeof module==='undefined'||!module.exports,B=browser?root.DormGame:require('./journeys.js');
const delta=(a,b)=>Object.fromEntries(B.keys.filter(k=>Number.isFinite(a[k])&&a[k]!==b[k]).map(k=>[k,b[k]-a[k]]));
function failure(s){const v=s.stats;return Number.isFinite(v.health)&&v.health<=0?'fail-health':Number.isFinite(v.mood)&&v.mood<=0?'fail-mood':v.energy<=0?'fail-energy':v.study<=0?'fail-study':s.term?.missed>=2?'fail-course':null;}
function addFlags(flags,entries){const next={...flags};for(const entry of entries)for(const [key,value] of Object.entries(entry.flags||{}))next[key]=(next[key]||0)+value;return next;}
function enableAudit(s){if(s.version!==6||s.auditFixes||s.phase==='ending')return s;const missing=s.log.filter(e=>e.origin==='relationship');return{...s,flags:addFlags(s.flags,missing),failed:s.failed||failure(s),auditFixes:{revision:1},actions:[...s.actions,'X']};}
const create=(...args)=>enableAudit(B.create(...args));
function getScene(s){const p=s.relationships?.pending;if(s.auditFixes&&s.phase==='outcome'&&p?.done&&s.outcome)return{id:s.eventId,time:s.outcome.time,kind:'心动日常',place:s.outcome.title==='说好的甜品，今天一起慢慢挑。'?'食堂 · 甜品窗口':'校园 · 两个人的安排',emoji:'💗',romanceScene:true,bubble:p.key==='bond-repair'?'相处遇到了问题，也可以一起处理。':'把对方的话，认真记在心里。',title:s.outcome.title,text:'',choices:[]};return B.getScene(s);}
function choose(s,index){let n=B.choose(s,index);if(!s.auditFixes)return n;const added=n.log.length>s.log.length?n.log.slice(s.log.length):[];const relationshipEntries=added.filter(e=>e.origin==='relationship');if(relationshipEntries.length)n={...n,flags:addFlags(n.flags,relationshipEntries)};if(n.phase==='outcome'&&!n.failed){const failed=failure(n);if(failed)n={...n,failed};}return n;}
function hasReturnedOutcome(s){return !!(s.journeys?.pending?.done||s.relationships?.pending?.done||s.campusRevision?.proposal?.done||s.evolution?.care?.done||(s.eventId==='evo-breakup'&&s.evolution?.breakPrevious));}
function restoredOutcome(s){if(!s.auditFixes||s.phase!=='outcome'||s.failed||!hasReturnedOutcome(s))return null;const restored=B.next(s);return restored.phase==='outcome'&&!restored.failed?restored:null;}
function next(s){if(!s.auditFixes||s.phase!=='outcome'||s.failed||!hasReturnedOutcome(s))return B.next(s);const restored=B.next(s);if(restored.phase!=='outcome'||restored.failed)return restored;const advanced=B.next(restored);return{...advanced,actions:[...s.actions,'Y']};}
function availableActivities(s){const restored=restoredOutcome(s);return B.availableActivities(restored||s);}
function startActivity(s,key){const restored=restoredOutcome(s);if(!restored)return B.startActivity(s,key);const next=B.startActivity(restored,key);return{...next,actions:[...s.actions,'P:'+key]};}
function missedTomorrow(s){return !!s.auditFixes&&s.phase==='dayEnd'&&!!s.romance?.connected&&!!s.relationships?.promise&&s.day>=s.relationships.promise.dueDay;}
function restPreview(s){const rest=B.restPreview(s);if(!missedTomorrow(s))return rest;const stats={...rest.stats,mood:Math.max(0,rest.stats.mood-3)};return{...rest,stats,changes:delta(s.stats,stats),failed:rest.failed||failure({...s,stats})};}
function continueDay(s){const rest=missedTomorrow(s)?restPreview(s):null,n=B.continueDay(s);return rest?{...n,rest}:n;}
function restore(raw){if(!raw?.auditFixes)return B.restore(raw);try{if(raw.version!==6||!Number.isInteger(raw.seed)||!Array.isArray(raw.actions)||raw.actions.length>30000)return null;let s=B.createHistorical(raw.seed,raw.traits,raw.name,raw.recent);const upgrades={h:'enableCare',b:'enableBalance',v:'enableRomance',p:'enableStory',y:'enableRhythm',f:'enableFood',i:'enableIllness',q:'enableMeetings',w:'enableWellness',u:'enableCampus',t:'enableEvolution',j:'enableLottery',k:'enableCampusRevision',g:'enableDining',z:'enableSocialUpdate',R:'enableRelationships',e:'enableEconomy',l:'enableLife'};
 for(const a of raw.actions){if(/^c[0-4]$/.test(a))s=choose(s,+a[1]);else if(a==='n')s=B.next(s);else if(a==='Y')s=next(s);else if(a==='d')s=continueDay(s);else if(a==='r')s=B.retire(s);else if(a==='m')s=B.enableCharacter(s,raw.character.selected,raw.character.fresh);else if(a==='J')s=B.enableJourneys(s,raw.journeys.backgroundId);else if(a==='X')s=enableAudit(s);else if(upgrades[a])s=B[upgrades[a]](s);else if(typeof a==='string'&&a.startsWith('a:'))s=B.startActivity(s,a.slice(2));else if(typeof a==='string'&&a.startsWith('P:'))s=startActivity(s,a.slice(2));else return null;}return JSON.stringify(s)===JSON.stringify(raw)?s:null;}catch{return null;}}
const api={...B,create,enableAudit,getScene,choose,next,continueDay,restPreview,availableActivities,startActivity,restore,valid:s=>restore(s)!==null};root.DormGame=api;if(!browser)module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
